fn convert_to_svg(
    text: &str,
    background: &str,
    fill_color: &str,
    stroke_color: &str,
    font_family: &str,
    font_size: i32,
    stroke_width: i32,
    scale: f64,
) -> String {
    // Calculate dimensions - rough estimate based on character count
    let width = ((text.lines().map(|l| l.len()).max().unwrap_or(0) as i32).max(1)) * 8;
    let height = ((text.lines().count() as i32).max(1)) * 16;

    let scaled_width = (width as f64 * scale) as i32;
    let scaled_height = (height as f64 * scale) as i32;
    let scaled_font_size = (font_size as f64 * scale) as i32;

    let mut svg = String::new();
    svg.push_str(&format!("<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"{}\" height=\"{}\" class=\"svgbob\">\n", scaled_width, scaled_height));

    svg.push_str("  <style>.svgbob line, .svgbob path, .svgbob circle, .svgbob rect, .svgbob polygon {\n");
    svg.push_str(&format!("  stroke: {};\n", stroke_color));
    svg.push_str(&format!("  stroke-width: {};\n", stroke_width));
    svg.push_str("  stroke-opacity: 1;\n");
    svg.push_str("  fill-opacity: 1;\n");
    svg.push_str("  stroke-linecap: round;\n");
    svg.push_str("  stroke-linejoin: miter;\n");
    svg.push_str("}\n\n");

    svg.push_str(".svgbob text {\n");
    svg.push_str("  white-space: pre;\n");
    svg.push_str(&format!("  fill: {};\n", stroke_color));
    svg.push_str(&format!("  font-family: {};\n", font_family));
    svg.push_str(&format!("  font-size: {}px;\n", scaled_font_size));
    svg.push_str("}\n\n");

    svg.push_str(".svgbob rect.backdrop {\n");
    svg.push_str("  stroke: none;\n");
    svg.push_str(&format!("  fill: {};\n", background));
    svg.push_str("}\n\n");

    svg.push_str(".svgbob .broken {\n");
    svg.push_str("  stroke-dasharray: 8;\n");
    svg.push_str("}\n\n");

    svg.push_str(".svgbob .filled {\n");
    svg.push_str(&format!("  fill: {};\n", fill_color));
    svg.push_str("}\n\n");

    svg.push_str(".svgbob .bg_filled {\n");
    svg.push_str(&format!("  fill: {};\n", background));
    svg.push_str("  stroke-width: 1;\n");
    svg.push_str("}\n\n");

    svg.push_str(".svgbob .nofill {\n");
    svg.push_str(&format!("  fill: {};\n", background));
    svg.push_str("}\n\n");

    svg.push_str(".svgbob .end_marked_arrow {\n");
    svg.push_str("  marker-end: url(#arrow);\n");
    svg.push_str("}\n\n");

    svg.push_str(".svgbob .start_marked_arrow {\n");
    svg.push_str("  marker-start: url(#arrow);\n");
    svg.push_str("}\n\n");

    svg.push_str(".svgbob .end_marked_diamond {\n");
    svg.push_str("  marker-end: url(#diamond);\n");
    svg.push_str("}\n\n");

    svg.push_str(".svgbob .start_marked_diamond {\n");
    svg.push_str("  marker-start: url(#diamond);\n");
    svg.push_str("}\n\n");

    svg.push_str(".svgbob .end_marked_circle {\n");
    svg.push_str("  marker-end: url(#circle);\n");
    svg.push_str("}\n\n");

    svg.push_str(".svgbob .start_marked_circle {\n");
    svg.push_str("  marker-start: url(#circle);\n");
    svg.push_str("}\n\n");

    svg.push_str(".svgbob .end_marked_open_circle {\n");
    svg.push_str("  marker-end: url(#open_circle);\n");
    svg.push_str("}\n\n");

    svg.push_str(".svgbob .start_marked_open_circle {\n");
    svg.push_str("  marker-start: url(#open_circle);\n");
    svg.push_str("}\n\n");

    svg.push_str(".svgbob .end_marked_big_open_circle {\n");
    svg.push_str("  marker-end: url(#big_open_circle);\n");
    svg.push_str("}\n\n");

    svg.push_str(".svgbob .start_marked_big_open_circle {\n");
    svg.push_str("  marker-start: url(#big_open_circle);\n");
    svg.push_str("}\n\n");

    svg.push_str("</style>\n");

    svg.push_str("  <defs>\n");
    svg.push_str("    <marker id=\"arrow\" viewBox=\"-2 -2 8 8\" refX=\"4\" refY=\"2\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n");
    svg.push_str("      <polygon points=\"0,0 0,4 4,2 0,0\"></polygon>\n");
    svg.push_str("    </marker>\n");
    svg.push_str("    <marker id=\"diamond\" viewBox=\"-2 -2 8 8\" refX=\"4\" refY=\"2\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n");
    svg.push_str("      <polygon points=\"0,2 2,0 4,2 2,4 0,2\"></polygon>\n");
    svg.push_str("    </marker>\n");
    svg.push_str("    <marker id=\"circle\" viewBox=\"0 0 8 8\" refX=\"4\" refY=\"4\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n");
    svg.push_str("      <circle cx=\"4\" cy=\"4\" r=\"2\" class=\"filled\"></circle>\n");
    svg.push_str("    </marker>\n");
    svg.push_str("    <marker id=\"open_circle\" viewBox=\"0 0 8 8\" refX=\"4\" refY=\"4\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n");
    svg.push_str("      <circle cx=\"4\" cy=\"4\" r=\"2\" class=\"bg_filled\"></circle>\n");
    svg.push_str("    </marker>\n");
    svg.push_str("    <marker id=\"big_open_circle\" viewBox=\"0 0 8 8\" refX=\"4\" refY=\"4\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n");
    svg.push_str("      <circle cx=\"4\" cy=\"4\" r=\"3\" class=\"bg_filled\"></circle>\n");
    svg.push_str("    </marker>\n");
    svg.push_str("  </defs>\n");

    svg.push_str(&format!("  <rect class=\"backdrop\" x=\"0\" y=\"0\" width=\"{}\" height=\"{}\"></rect>\n", scaled_width, scaled_height));

    svg.push_str("</svg>\n");

    svg
}

fn handle_build(input_pattern: Option<String>, output_dir: Option<String>) {
    let input = input_pattern.unwrap_or_else(|| "*.bob".to_string());
    let outdir = output_dir.unwrap_or_else(|| ".".to_string());

    // Create output directory if it doesn't exist
    let _ = fs::create_dir_all(&outdir);

    // Simple glob implementation - just look for matching files
    let parts: Vec<&str> = input.split('/').collect();
    let pattern = parts.last().unwrap_or(&"*.bob");
    let search_dir = if parts.len() > 1 {
        parts[..parts.len() - 1].join("/")
    } else {
        ".".to_string()
    };

    // Find matching files
    if let Ok(entries) = fs::read_dir(&search_dir) {
        for entry in entries {
            if let Ok(entry) = entry {
                let path = entry.path();
                let filename = path.file_name().unwrap().to_string_lossy().to_string();

                // Check if filename matches pattern
                let pattern_regex = pattern.replace("*", ".*");
                if filename.contains(".bob") || (pattern.contains("*") && pattern_matches(&filename, pattern)) {
                    if let Ok(content) = fs::read_to_string(&path) {
                        let svg = convert_to_svg(
                            &content,
                            "white",
                            "black",
                            "black",
                            "arial",
                            14,
                            2,
                            1.0,
                        );

                        let stem = path.file_stem().unwrap().to_string_lossy().to_string();
                        let output_path = format!("{}/{}.svg", outdir, stem);

                        if let Ok(_) = fs::write(&output_path, &svg) {
                            eprintln!("{} => {}", path.display(), output_path);
                        }
                    }
                }
            }
        }
    }
}

fn pattern_matches(filename: &str, pattern: &str) -> bool {
    // Simple wildcard matching
    if pattern == "*" {
        return true;
    }
    if !pattern.contains("*") {
        return filename == pattern;
    }
    let parts: Vec<&str> = pattern.split("*").collect();
    if parts.is_empty() {
        return true;
    }

    let mut pos = 0;
    for (i, part) in parts.iter().enumerate() {
        if i == 0 && !part.is_empty() {
            if !filename.starts_with(part) {
                return false;
            }
            pos += part.len();
        } else if i == parts.len() - 1 && !part.is_empty() {
            if !filename.ends_with(part) {
                return false;
            }
        } else if !part.is_empty() {
            if let Some(idx) = filename[pos..].find(part) {
                pos += idx + part.len();
            } else {
                return false;
            }
        }
    }

    true
}
