fn try_parse_line(grid: &[Vec<char>], processed: &mut [Vec<bool>], x: usize, y: usize, scale: f64, horizontal: bool) -> Option<String> {
    if horizontal {
        let mut x2 = x;
        while x2 < grid[y].len() && matches!(grid[y][x2], '-' | '_' | '>' | 'o' | '*') {
            x2 += 1;
        }
        x2 -= 1;

        if x2 <= x {
            return None;
        }

        for xx in x..=x2 {
            processed[y][xx] = true;
        }

        let x1 = (x as f64 * 8.0 * scale) as i32 + 8;
        let x2_px = ((x2 + 1) as f64 * 8.0 * scale) as i32;
        let y_px = (y as f64 * 16.0 * scale) as i32 + 8;

        Some(format!(
            "  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>",
            x1, y_px, x2_px, y_px
        ))
    } else {
        let mut y2 = y;
        while y2 < grid.len() && grid[y2][x] == '|' {
            y2 += 1;
        }
        y2 -= 1;

        if y2 <= y {
            return None;
        }

        for yy in y..=y2 {
            processed[yy][x] = true;
        }

        let x_px = (x as f64 * 8.0 * scale) as i32 + 8;
        let y1_px = (y as f64 * 16.0 * scale) as i32 + 8;
        let y2_px = ((y2 + 1) as f64 * 16.0 * scale) as i32 + 8;

        Some(format!(
            "  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>",
            x_px, y1_px, x_px, y2_px
        ))
    }
}

