                println!("    -i, --input <input>      set input file pattern like: *.bob or dir/*.bob");
                println!("    -o, --outdir <outdir>    set dir of svg files");
                return;
            }
            "-V" | "--version" => {
                println!("executable-build 0.0.1");
                return;
            }
            "-i" | "--input" => {
                if i + 1 < args.len() {
                    input_pattern = Some(args[i + 1].clone());
                    i += 2;
                } else {
                    i += 1;
                }
            }
            "-o" | "--outdir" => {
                if i + 1 < args.len() {
                    output_dir = Some(args[i + 1].clone());
                    i += 2;
