fn parse_ascii(text: &str, scale: f64) -> Vec<String> {
    let mut elements = Vec::new();
    let lines: Vec<&str> = text.lines().collect();

    // Convert text to character grid
    let max_width = lines.iter().map(|l| l.len()).max().unwrap_or(0);
    let mut grid: Vec<Vec<char>> = Vec::new();

    for line in &lines {
        let mut row = Vec::new();
        for c in line.chars() {
            row.push(c);
        }
        while row.len() < max_width {
            row.push(' ');
        }
        grid.push(row);
    }

    // Simple parsing: look for patterns
    let mut processed = vec![vec![false; max_width]; grid.len()];

    for y in 0..grid.len() {
        for x in 0..grid[y].len() {
            if processed[y][x] {
                continue;
            }

            let ch = grid[y][x];

            // Parse rectangles
            if ch == '+' {
                if let Some(elem) = try_parse_rect(&grid, &mut processed, x, y, scale) {
                    elements.push(elem);
                }
            }
            // Parse circles/arcs
            else if ch == '(' || ch == ')' {
                if let Some(elem) = try_parse_circle(&grid, &mut processed, x, y, scale) {
                    elements.push(elem);
                }
            }
            // Parse horizontal lines
            else if ch == '-' || ch == '_' {
                if let Some(elem) = try_parse_line(&grid, &mut processed, x, y, scale, true) {
                    elements.push(elem);
                }
            }
            // Parse vertical lines
            else if ch == '|' {
                if let Some(elem) = try_parse_line(&grid, &mut processed, x, y, scale, false) {
                    elements.push(elem);
                }
            }
            // Parse arrows
            else if ch == 'o' || ch == '*' || ch == '>' || ch == '<' || ch == '^' || ch == 'v' {
                if let Some(elem) = try_parse_arrow(&grid, &mut processed, x, y, scale) {
                    elements.push(elem);
                }
            }
            // Regular text
            else if !ch.is_whitespace() && !is_shape_char(ch) {
                elements.push(format!(
                    "  <text x=\"{}\" y=\"{}\" >{}</text>",
                    (x as f64 * 8.0 * scale) as i32 + 8,
                    (y as f64 * 16.0 * scale) as i32 + 12,
                    ch
                ));
                processed[y][x] = true;
            }
        }
    }

    elements
}

fn is_shape_char(c: char) -> bool {
    matches!(c, '+' | '-' | '|' | '_' | '/' | '\\' | '(' | ')' | '*' | 'o' | '>' | '<' | '^' | 'v')
}

fn try_parse_rect(grid: &[Vec<char>], processed: &mut [Vec<bool>], x: usize, y: usize, scale: f64) -> Option<String> {
    // Find rectangle bounds
    let mut x2 = x;
    while x2 < grid[y].len() && grid[y][x2] == '+' {
        x2 += 1;
    }
    x2 -= 1;

    if x2 <= x {
        return None;
    }

    let mut y2 = y;
    while y2 < grid.len() && grid[y2][x] == '+' {
        y2 += 1;
    }
    y2 -= 1;

    if y2 <= y {
        return None;
    }

    // Check corners are all +
    if grid[y2][x2] != '+' || grid[y][x2] != '+' || grid[y2][x] != '+' {
        return None;
    }

    // Verify horizontal and vertical lines
    let mut valid = true;
    for xx in (x + 1)..x2 {
        if !matches!(grid[y][xx], '-' | '_' | '+') {
            valid = false;
            break;
        }
    }

    if valid {
        for xx in (x + 1)..x2 {
            if !matches!(grid[y2][xx], '-' | '_' | '+') {
                valid = false;
                break;
            }
        }
    }

    if !valid {
        return None;
    }

    // Mark as processed
    for yy in y..=y2 {
        for xx in x..=x2 {
            processed[yy][xx] = true;
        }
    }

    let rect_x = (x as f64 * 8.0 * scale) as i32;
    let rect_y = (y as f64 * 16.0 * scale) as i32 + 8;
    let rect_width = ((x2 - x) as f64 * 8.0 * scale) as i32;
    let rect_height = ((y2 - y) as f64 * 16.0 * scale) as i32;

    Some(format!(
        "  <rect x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\" class=\"solid nofill\" rx=\"0\"></rect>",
        rect_x, rect_y, rect_width, rect_height
    ))
}

