fn parse_ascii(text: &str, scale: f64) -> Vec<String> {
    let mut elements = Vec::new();
    let lines: Vec<&str> = text.lines().collect();

    if lines.is_empty() {
        return elements;
    }

    // Create grid with proper padding
    let max_width = lines.iter().map(|l| l.len()).max().unwrap_or(0);
    let mut grid: Vec<Vec<char>> = Vec::new();

    for line in &lines {
        let mut row = Vec::new();
        for c in line.chars() {
            row.push(c);
        }
        while row.len() < max_width {
            row.push(' ');
        }
        grid.push(row);
    }

    let mut processed = vec![vec![false; max_width]; grid.len()];

    // Look for rectangles first (boxes with +, -, |)
    for y in 0..grid.len() {
        for x in 0..grid[y].len() {
            if processed[y][x] || grid[y][x] != '+' {
                continue;
            }

            if let Some(elem) = parse_rectangle(&grid, &mut processed, x, y, scale) {
                elements.push(elem);
            }
        }
    }

    // Look for lines and shapes
    for y in 0..grid.len() {
        for x in 0..grid[y].len() {
            if processed[y][x] {
                continue;
            }

            let ch = grid[y][x];

            if ch == 'o' || ch == '*' {
                // Try to parse arrow/circle
                if let Some(elem) = parse_arrow_or_circle(&grid, &mut processed, x, y, scale) {
                    elements.push(elem);
                } else if !processed[y][x] {
                    // Render as text
                    elements.push(format!(
                        "  <text x=\"{}\" y=\"{}\" >{}</text>",
                        (x as f64 * 8.0 * scale) as i32 + 2,
                        (y as f64 * 16.0 * scale) as i32 + 12,
                        ch
                    ));
                    processed[y][x] = true;
                }
            } else if ch == '-' || ch == '_' || ch == '=' {
                // Parse horizontal line
                if let Some(elem) = parse_horizontal_line(&grid, &mut processed, x, y, scale) {
                    elements.push(elem);
                }
            } else if ch == '|' {
                // Parse vertical line
                if let Some(elem) = parse_vertical_line(&grid, &mut processed, x, y, scale) {
                    elements.push(elem);
                }
            } else if ch == '(' || ch == ')' {
                // Try to parse arc/circle
                if let Some(elem) = parse_arc(&grid, &mut processed, x, y, scale) {
                    elements.push(elem);
                }
            } else if !ch.is_whitespace() {
                // Regular text
                elements.push(format!(
                    "  <text x=\"{}\" y=\"{}\" >{}</text>",
                    (x as f64 * 8.0 * scale) as i32 + 2,
                    (y as f64 * 16.0 * scale) as i32 + 12,
                    ch
                ));
                processed[y][x] = true;
            }
        }
    }

    elements
}

fn parse_rectangle(grid: &[Vec<char>], processed: &mut [Vec<bool>], x: usize, y: usize, scale: f64) -> Option<String> {
    // Find extent to the right
    let mut x2 = x;
    while x2 < grid[y].len() && (grid[y][x2] == '+' || grid[y][x2] == '-' || grid[y][x2] == '_') {
        x2 += 1;
    }
    x2 -= 1;

    if x2 <= x || grid[y][x2] != '+' {
        return None;
    }

    // Find extent downward
    let mut y2 = y;
    while y2 < grid.len() && (grid[y2][x] == '+' || grid[y2][x] == '|') {
        y2 += 1;
    }
    y2 -= 1;

    if y2 <= y || grid[y2][x] != '+' {
        return None;
    }

    // Check if bottom-right is +
    if x2 >= grid[y2].len() || grid[y2][x2] != '+' {
        return None;
    }

    // Check if bottom-left is +
    if grid[y2][x] != '+' {
        return None;
    }

    // Verify top and bottom edges are mostly - or +
    let mut valid = true;
    for xx in (x + 1)..x2 {
        if !matches!(grid[y][xx], '-' | '_' | '+') {
            valid = false;
            break;
        }
        if !matches!(grid[y2][xx], '-' | '_' | '+') {
            valid = false;
            break;
        }
    }

    if !valid {
        return None;
    }

    // Verify left and right edges
    for yy in (y + 1)..y2 {
        if grid[yy][x] != '|' && grid[yy][x] != '+' {
            valid = false;
            break;
        }
        if grid[yy][x2] != '|' && grid[yy][x2] != '+' {
            valid = false;
            break;
        }
    }

    if !valid {
        return None;
    }

    // Mark processed
    for yy in y..=y2 {
        for xx in x..=x2 {
            processed[yy][xx] = true;
        }
    }

    let rect_x = (x as f64 * 8.0 * scale) as i32;
    let rect_y = (y as f64 * 16.0 * scale) as i32 + 8;
    let rect_width = ((x2 - x) as f64 * 8.0 * scale) as i32;
    let rect_height = ((y2 - y) as f64 * 16.0 * scale) as i32;

    Some(format!(
        "  <rect x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\" class=\"solid nofill\" rx=\"0\"></rect>",
        rect_x, rect_y, rect_width, rect_height
    ))
}

fn parse_horizontal_line(grid: &[Vec<char>], processed: &mut [Vec<bool>], x: usize, y: usize, scale: f64) -> Option<String> {
    let start_x = x;
    let mut end_x = x;

    while end_x < grid[y].len() && matches!(grid[y][end_x], '-' | '_' | '=' | 'o' | '*' | '>') {
        end_x += 1;
    }
    end_x -= 1;

    if end_x <= start_x {
        return None;
    }

    let has_start_marker = if start_x > 0 { matches!(grid[y][start_x - 1], 'o' | '*' | '<') } else { false };
    let has_end_marker = if end_x + 1 < grid[y].len() { matches!(grid[y][end_x + 1], 'o' | '*' | '>') } else { false };

    for xx in start_x..=end_x {
        processed[y][xx] = true;
    }

    let x1 = ((start_x) as f64 * 8.0 * scale) as i32 + 8;
    let x2 = ((end_x + 1) as f64 * 8.0 * scale) as i32;
    let yy = (y as f64 * 16.0 * scale) as i32 + 8;

    let mut class = "solid".to_string();
    let mut element = format!(
        "  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"{}\"></line>",
        x1, yy, x2, yy, class
    );

    // Handle arrow head
    if has_end_marker {
        let arrow_x = x2;
        let arrow_y = yy;
        elements.push(format!(
            "  <polygon points=\"{},{} {},{}  {},{} class=\"filled\"></polygon>",
            arrow_x, arrow_y - 4,
            arrow_x + 8, arrow_y,
            arrow_x, arrow_y + 4
        ));
    }

    Some(element)
}

fn parse_vertical_line(grid: &[Vec<char>], processed: &mut [Vec<bool>], x: usize, y: usize, scale: f64) -> Option<String> {
    let start_y = y;
    let mut end_y = y;

    while end_y < grid.len() && grid[end_y][x] == '|' {
        end_y += 1;
    }
    end_y -= 1;

    if end_y <= start_y {
        return None;
    }

    for yy in start_y..=end_y {
        processed[yy][x] = true;
    }

    let xx = (x as f64 * 8.0 * scale) as i32 + 8;
    let y1 = ((start_y) as f64 * 16.0 * scale) as i32 + 8;
    let y2 = ((end_y + 1) as f64 * 16.0 * scale) as i32 + 8;

    Some(format!(
        "  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>",
        xx, y1, xx, y2
    ))
}

fn parse_arrow_or_circle(grid: &[Vec<char>], processed: &mut [Vec<bool>], x: usize, y: usize, scale: f64) -> Option<String> {
    let ch = grid[y][x];
    if ch != 'o' && ch != '*' {
        return None;
    }

    processed[y][x] = true;

    // Try to parse as arrow
    // Check if there's a line to the right
    if x + 1 < grid[y].len() && matches!(grid[y][x + 1], '-' | '_' | '>') {
        // Parse right arrow
        let mut end_x = x + 1;
        while end_x < grid[y].len() && matches!(grid[y][end_x], '-' | '_' | '>') {
            end_x += 1;
        }
        end_x -= 1;

        for xx in (x + 1)..=end_x {
            processed[y][xx] = true;
        }

        let x1 = ((x + 1) as f64 * 8.0 * scale) as i32 + 8;
        let x2 = ((end_x + 1) as f64 * 8.0 * scale) as i32;
        let yy = (y as f64 * 16.0 * scale) as i32 + 8;

        // Add line
        let line_class = if ch == 'o' { "solid end_marked_open_circle" } else { "solid" };

        let mut result = format!(
            "  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"{}\"></line>",
            x1, yy, x2, yy, line_class
        );

        // Add arrow head
        result.push_str(&format!(
            "\n  <polygon points=\"{},{} {},{}  {},{}\" class=\"filled\"></polygon>",
            x2, yy - 4,
            x2 + 8, yy,
            x2, yy + 4
        ));

        return Some(result);
    }

    None
}

fn parse_arc(grid: &[Vec<char>], processed: &mut [Vec<bool>], x: usize, y: usize, scale: f64) -> Option<String> {
    let ch = grid[y][x];
    if ch != '(' && ch != ')' {
        return None;
    }

    // Try to find matching paren
    let mut pair_x = x;
    if ch == '(' {
        while pair_x < grid[y].len() && grid[y][pair_x] != ')' {
            pair_x += 1;
        }
        if pair_x >= grid[y].len() {
            return None;
        }
    } else {
        while pair_x > 0 && grid[y][pair_x] != '(' {
            pair_x -= 1;
        }
        if grid[y][pair_x] != '(' {
            return None;
        }
    }

    // Mark as processed
    for xx in x.min(pair_x)..=x.max(pair_x) {
        processed[y][xx] = true;
    }

    // Check if there's text inside
    let mut text = String::new();
    for xx in (x + 1)..pair_x {
        if grid[y][xx] != ' ' {
            text.push(grid[y][xx]);
        }
    }

    let center_x = ((x + pair_x) as f64 / 2.0 * 8.0 * scale) as i32 + 8;
    let center_y = (y as f64 * 16.0 * scale) as i32 + 8;
    let radius = ((pair_x - x) as f64 * 4.0 * scale) as i32;

    let mut result = String::new();

    // Add arcs
    result.push_str(&format!(
        "  <path d=\"M {},{}  A {},{} 0,0,0 {},{}\" class=\"nofill\"></path>",
        center_x - radius, center_y,
        radius, radius,
        center_x + radius, center_y
    ));

    // Add text if present
    if !text.is_empty() {
        result.push_str(&format!(
            "\n  <text x=\"{}\" y=\"{}\" >{}</text>",
            center_x - 2, center_y + 4, text
        ));
    }

    // Add bottom arc
    result.push_str(&format!(
        "\n  <path d=\"M {},{}  A {},{} 0,0,1 {},{}\" class=\"nofill\"></path>",
        center_x + radius, center_y,
        radius, radius,
        center_x - radius, center_y
    ));

    Some(result)
}

