#[derive(Clone)]
struct CliOpts {
    inline: bool,
    inline_string: Option<String>,
    output: Option<String>,
    background: String,
    fill_color: String,
    stroke_color: String,
    font_family: String,
    font_size: i32,
    stroke_width: i32,
    scale: f64,
}

impl Default for CliOpts {
    fn default() -> Self {
        CliOpts {
            inline: false,
            inline_string: None,
            output: None,
            background: "white".to_string(),
            fill_color: "black".to_string(),
