    let width = (max_width * 8).max(8);
    let height_px = (height * 16).max(16);

    let scaled_width = (width as f64 * opts.scale) as i32;
    let scaled_height = (height_px as f64 * opts.scale) as i32;
    let scaled_font_size = (opts.font_size as f64 * opts.scale) as i32;

