fn convert_to_svg(text: &str, opts: &CliOpts) -> String {
    let lines: Vec<&str> = text.lines().collect();
    let max_width = lines.iter().map(|l| l.len()).max().unwrap_or(1);
    let height = lines.len().max(1);

    // Calculate SVG dimensions
    let width = (max_width * 8).max(8);
    let height_px = (height * 16).max(16);

    let scaled_width = (width as f64 * opts.scale) as i32;
    let scaled_height = (height_px as f64 * opts.scale) as i32;
    let scaled_font_size = (opts.font_size as f64 * opts.scale) as i32;

    let mut svg = String::new();
    svg.push_str(&format!(
        "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"{}\" height=\"{}\" class=\"svgbob\">\n",
        scaled_width, scaled_height
    ));

    // CSS styles
    svg.push_str("  <style>.svgbob line, .svgbob path, .svgbob circle, .svgbob rect, .svgbob polygon {\n");
    svg.push_str(&format!("  stroke: {};\n", opts.stroke_color));
    svg.push_str(&format!("  stroke-width: {};\n", opts.stroke_width));
    svg.push_str("  stroke-opacity: 1;\n");
    svg.push_str("  fill-opacity: 1;\n");
    svg.push_str("  stroke-linecap: round;\n");
    svg.push_str("  stroke-linejoin: miter;\n");
    svg.push_str("}\n\n");

    svg.push_str(".svgbob text {\n");
    svg.push_str("  white-space: pre;\n");
    svg.push_str(&format!("  fill: {};\n", opts.stroke_color));
    svg.push_str(&format!("  font-family: {};\n", opts.font_family));
    svg.push_str(&format!("  font-size: {}px;\n", scaled_font_size));
    svg.push_str("}\n\n");

    svg.push_str(".svgbob rect.backdrop {\n");
    svg.push_str("  stroke: none;\n");
    svg.push_str(&format!("  fill: {};\n", opts.background));
    svg.push_str("}\n\n");

    svg.push_str(".svgbob .broken {\n");
    svg.push_str("  stroke-dasharray: 8;\n");
    svg.push_str("}\n\n");

    svg.push_str(".svgbob .filled {\n");
    svg.push_str(&format!("  fill: {};\n", opts.fill_color));
    svg.push_str("}\n\n");

    svg.push_str(".svgbob .bg_filled {\n");
    svg.push_str(&format!("  fill: {};\n", opts.background));
    svg.push_str("  stroke-width: 1;\n");
    svg.push_str("}\n\n");

    svg.push_str(".svgbob .nofill {\n");
    svg.push_str(&format!("  fill: {};\n", opts.background));
    svg.push_str("}\n\n");

    add_marker_styles(&mut svg);
    svg.push_str("</style>\n");

    // Defs with markers
    svg.push_str("  <defs>\n");
    add_markers(&mut svg);
    svg.push_str("  </defs>\n");

    // Background
    svg.push_str(&format!(
        "  <rect class=\"backdrop\" x=\"0\" y=\"0\" width=\"{}\" height=\"{}\"></rect>\n",
        scaled_width, scaled_height
    ));

    // Parse and render content
    let elements = parse_ascii(&text, opts.scale);
    for elem in elements {
        svg.push_str(&elem);
        svg.push('\n');
    }

    svg.push_str("</svg>\n");
    svg
}

