pub fn parse_ascii(text: &str, scale: f64) -> Vec<String> {
    let mut elements = Vec::new();
    let lines: Vec<&str> = text.lines().collect();

    if lines.is_empty() {
        return elements;
    }

    // Get grid dimensions
    let max_width = lines.iter().map(|l| l.len()).max().unwrap_or(0);
    if max_width == 0 {
        return elements;
    }

    // Build character grid
    let mut grid: Vec<Vec<char>> = Vec::new();
    for line in &lines {
        let mut row = Vec::new();
        for c in line.chars() {
            row.push(c);
        }
        while row.len() < max_width {
            row.push(' ');
        }
        grid.push(row);
    }

    // Track which cells have been processed
    let mut processed = vec![vec![false; max_width]; grid.len()];

    // Try to identify rectangles
    for y in 0..grid.len() {
        for x in 0..max_width {
            if processed[y][x] || grid[y][x] != '+' {
                continue;
            }

            if let Some(rect) = try_parse_rect(&grid, &mut processed, x, y, scale) {
                elements.push(rect);
            }
        }
    }

    // Try to identify horizontal lines and arrows
    for y in 0..grid.len() {
        for x in 0..max_width {
            if processed[y][x] || !matches!(grid[y][x], '-' | 'o' | '*' | '=') {
                continue;
            }

            if let Some(line) = try_parse_horiz_line(&grid, &mut processed, x, y, scale) {
                elements.push(line);
            }
        }
    }

    // Try to identify vertical lines
    for y in 0..grid.len() {
        for x in 0..max_width {
            if processed[y][x] || grid[y][x] != '|' {
                continue;
            }

            if let Some(line) = try_parse_vert_line(&grid, &mut processed, x, y, scale) {
                elements.push(line);
            }
        }
    }

    // Try to identify circles
    for y in 0..grid.len() {
        for x in 0..max_width {
            if processed[y][x] || grid[y][x] != '(' {
                continue;
            }

            if let Some(circle) = try_parse_circle(&grid, &mut processed, x, y, scale) {
                elements.push(circle);
            }
        }
    }

    // Remaining characters as text
    for y in 0..grid.len() {
        for x in 0..max_width {
            if !processed[y][x] && !grid[y][x].is_whitespace() {
                let text_elem = format!(
                    "  <text x=\"{}\" y=\"{}\" >{}</text>",
                    (x as f64 * 8.0 * scale) as i32 + 2,
                    (y as f64 * 16.0 * scale) as i32 + 12,
                    grid[y][x]
                );
                elements.push(text_elem);
                processed[y][x] = true;
            }
        }
    }

    elements
}

fn try_parse_rect(grid: &[Vec<char>], processed: &mut [Vec<bool>], x: usize, y: usize, scale: f64) -> Option<String> {
    let height = grid.len();
    let width = grid.get(0).map(|r| r.len()).unwrap_or(0);

    // Find right edge
    let mut x2 = x + 1;
    while x2 < width && matches!(grid[y][x2], '-' | '_' | '+') {
        x2 += 1;
    }
    x2 -= 1;

    if x2 <= x || grid[y][x2] != '+' {
        return None;
    }

    // Find bottom edge
    let mut y2 = y + 1;
    while y2 < height && grid[y2][x] == '|' {
        y2 += 1;
    }
    if y2 < height && grid[y2][x] == '+' {
        // y2 is correct
    } else {
        return None;
    }

    // Verify bottom right corner
    if grid[y2][x2] != '+' {
        return None;
    }

    // Mark as processed
    for yy in y..=y2 {
        for xx in x..=x2 {
            if processed[yy].get(xx).is_some() {
                processed[yy][xx] = true;
            }
        }
    }

    let rect_x = (x as f64 * 8.0 * scale) as i32;
    let rect_y = (y as f64 * 16.0 * scale) as i32 + 8;
    let rect_w = ((x2 - x) as f64 * 8.0 * scale) as i32;
    let rect_h = ((y2 - y) as f64 * 16.0 * scale) as i32;

    Some(format!(
        "  <rect x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\" class=\"solid nofill\" rx=\"0\"></rect>",
        rect_x, rect_y, rect_w, rect_h
    ))
}

fn try_parse_horiz_line(grid: &[Vec<char>], processed: &mut [Vec<bool>], x: usize, y: usize, scale: f64) -> Option<String> {
    let width = grid.get(0).map(|r| r.len()).unwrap_or(0);

    let mut x1 = x;
    let mut x2 = x;

    // Find end of line
    while x2 < width && matches!(grid[y][x2], '-' | '_' | '=' | 'o' | '*' | '>') {
        x2 += 1;
    }
    x2 -= 1;

    if x2 <= x1 {
        return None;
    }

    // Mark processed
    for xx in x1..=x2 {
        if processed[y].get(xx).is_some() {
            processed[y][xx] = true;
        }
    }

    let x1_px = ((x1) as f64 * 8.0 * scale) as i32 + 8;
    let x2_px = ((x2 + 1) as f64 * 8.0 * scale) as i32;
    let y_px = (y as f64 * 16.0 * scale) as i32 + 8;

    let mut result = format!(
        "  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>",
        x1_px, y_px, x2_px, y_px
    );

    // Check for arrow head
    if grid[y][x2] == '>' || (x2 + 1 < width && grid[y][x2 + 1] == '>') {
        result.push_str(&format!(
            "\n  <polygon points=\"{},{} {},{}  {},{}\" class=\"filled\"></polygon>",
            x2_px, y_px - 4,
            x2_px + 8, y_px,
            x2_px, y_px + 4
        ));
    }

    Some(result)
}

fn try_parse_vert_line(grid: &[Vec<char>], processed: &mut [Vec<bool>], x: usize, y: usize, scale: f64) -> Option<String> {
    let height = grid.len();

    let mut y1 = y;
    let mut y2 = y;

    while y2 < height && grid[y2][x] == '|' {
        y2 += 1;
    }
    y2 -= 1;

    if y2 <= y1 {
        return None;
    }

    // Mark processed
    for yy in y1..=y2 {
        if processed[yy].get(x).is_some() {
            processed[yy][x] = true;
        }
    }

    let x_px = (x as f64 * 8.0 * scale) as i32 + 8;
    let y1_px = ((y1) as f64 * 16.0 * scale) as i32 + 8;
    let y2_px = ((y2 + 1) as f64 * 16.0 * scale) as i32 + 8;

    Some(format!(
        "  <line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"solid\"></line>",
        x_px, y1_px, x_px, y2_px
    ))
}

fn try_parse_circle(grid: &[Vec<char>], processed: &mut [Vec<bool>], x: usize, y: usize, scale: f64) -> Option<String> {
    let width = grid.get(0).map(|r| r.len()).unwrap_or(0);

    // Find matching )
    let mut x2 = x + 1;
    let mut text_content = String::new();

    while x2 < width && grid[y][x2] != ')' {
        if !grid[y][x2].is_whitespace() {
            text_content.push(grid[y][x2]);
        }
        x2 += 1;
    }

    if x2 >= width || grid[y][x2] != ')' {
        return None;
    }

    // Mark processed
    for xx in x..=x2 {
        if processed[y].get(xx).is_some() {
            processed[y][xx] = true;
        }
    }

    let cx = ((x + x2) as f64 / 2.0 * 8.0 * scale) as i32 + 8;
    let cy = (y as f64 * 16.0 * scale) as i32 + 8;
    let radius = ((x2 - x) as f64 * 4.0 * scale) as i32;

    let mut result = String::new();
    result.push_str(&format!(
        "  <path d=\"M {},{} A {},{} 0,0,0 {},{}\" class=\"nofill\"></path>",
        cx - radius, cy,
        radius, radius,
        cx + radius, cy
    ));

    if !text_content.is_empty() {
        result.push_str(&format!(
            "\n  <text x=\"{}\" y=\"{}\" >{}</text>",
            cx - 2, cy + 4, text_content
        ));
    }

    result.push_str(&format!(
        "\n  <path d=\"M {},{} A {},{} 0,0,1 {},{}\" class=\"nofill\"></path>",
        cx + radius, cy,
        radius, radius,
        cx - radius, cy
    ));

    Some(result)
}
